#!/usr/bin/env python3
"""Private side-by-side owner comparison; never included in deployment output."""
import argparse,base64
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--reference',required=True);p.add_argument('--candidate',default='.private/stage5/art-ru-393.png');p.add_argument('--output',default='.private/stage5/reference-comparison.html');a=p.parse_args()
def data(path):return 'data:image/png;base64,'+base64.b64encode(Path(path).read_bytes()).decode()
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="robots" content="noindex"><title>Hytale Craft — сравнение этапа 5</title><style>*{box-sizing:border-box}body{margin:0;padding:20px;background:#071321;color:#e8f2fc;font:16px/1.4 system-ui}h1{font-size:24px}p{max-width:800px;color:#bad0df}.pair{display:grid;grid-template-columns:393px 393px;gap:20px}h2{font-size:18px}img{display:block;width:393px;height:auto;border:1px solid #4b6a80}small{color:#b9cede}@media(max-width:700px){.pair{grid-template-columns:minmax(0,1fr)}img{max-width:100%}}</style><h1>Hytale Craft · сравнение художественного направления</h1><p>Слева — основной сохранённый эталон владельца. Справа — новая проба только двух карточек, без готовности остальных восьми. Это частное сравнение, не публичная страница и не утверждение финального совпадения.</p><div class="pair"><section><h2>Эталон: тёмный мобильный макет</h2><img src="__REFERENCE_PNG_DATA__" alt="Основной эталон владельца"><small>Google Drive · 01_APPROVED_PRIMARY_dark_mobile_10_cards.png</small></section><section><h2>Этап 5: воин и шахтёр · 393 px</h2><img src="__CANDIDATE_PNG_DATA__" alt="Две новые карточки"><small>Оригинальные ИИ-пробы, HTML-подписи. Движения показаны отдельным видео.</small></section></div></html>'''.replace('__REFERENCE_PNG_DATA__',data(a.reference)).replace('__CANDIDATE_PNG_DATA__',data(a.candidate))
out=Path(a.output);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(html);print(out)
